import{_ as s,l as n,o as e,c as o,v as r,p as i,x as t,d as c,i as p,S as R}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"LRU / PLRU","description":"","frontmatter":{"title":"LRU / PLRU","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/lru-plru.md","filePath":"cs/lru-plru.md","lastUpdated":1789023840000}'),d={name:"cs/lru-plru.md"};function U(h,a,L,A,P,u){const l=n("Mermaid");return e(),o("div",null,[a[1]||(a[1]=r('<h1 id="lru-plru" tabindex="-1">LRU / PLRU <a class="header-anchor" href="#lru-plru" aria-label="Permalink to &quot;LRU / PLRU&quot;">​</a></h1><div class="epigraph"><p>组相联要在缺失时丢掉「最可能不再用」的那一路；真 LRU 的状态随路数阶乘涨，树状伪 LRU 用少得多的位逼近。</p><footer>—— 据 Hennessy and Patterson, CA:AQA；Belady 最优替换的对照 整理</footer></div><p><a href="/cs/deep-pipeline-clock">上一课</a> 收束乱序前端，下一条路是存储层次。<a href="/cs/locality-principle">局部性</a> 已经要求「留下最近用的」。<a href="/cs/cache-miss-types">缺失分类</a> 把冲突与容量分开。本课不重讲五级的 cache 时序。缺口是<strong>组相联里具体怎么选牺牲者：真 LRU 与工业常用的 PLRU</strong>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>直接映射没有替换：索引唯一决定路。2–16 路时，缺失要在组内挑一块踢掉。Belady 的 MIN 需要未来引用，硬件没有。栈算法意义上的 LRU：丢掉最久未访问的那路，对许多访问模式接近 MIN。但 \\(n\\) 路真 LRU 要记 \\(n!\\) 种排列或至少 \\(n\\log n\\) 量级的年龄，16 路已经烦。缺口不是更大的 cache，而是<strong>用可实现的位实现「接近 LRU」</strong>。</p><p><span class="marginnote">PLRU：满二叉树，每个内节点一位指向「更 LRU 的一侧」。命中把路径拨向对方；替换沿指针走到叶子。位数是 \\(n-1\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>真 LRU：组内维护年龄链或时间戳，命中则提到 MRU，替换踢 LRU。PLRU：命中沿根到该路把各位翻成「另一侧更老」；替换从根跟随「老侧」指针。随机/轮转更便宜，冲突模式下更差。</p>',8)),(e(),i(R,null,{default:t(()=>[p(l,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20MISS%5B%22%E7%BB%84%E5%86%85%E7%BC%BA%E5%A4%B1%22%5D%20--%3E%20LRU%5B%22%E7%9C%9F%20LRU%EF%BC%9A%E8%B8%A2%E6%9C%80%E4%B9%85%E6%9C%AA%E7%94%A8%22%5D%0A%20%20MISS%20--%3E%20PLRU%5B%22PLRU%EF%BC%9A%E6%B2%BF%E6%A0%91%E6%8C%87%E9%92%88%E8%B8%A2%22%5D%0A%20%20HIT%5B%22%E5%91%BD%E4%B8%AD%22%5D%20--%3E%20UPD%5B%22%E6%8A%8A%E8%AF%A5%E8%B7%AF%E6%A0%87%E4%B8%BA%20MRU%20%2F%20%E6%8B%A8%E6%A0%91%E4%BD%8D%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>写回 cache：被踢的若脏则先写回，替换延迟叠在缺失上。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>冲突缺失对 LRU 敏感：循环扫描刚好大于组的工作集时，LRU 会系统性踢「即将再用」的块（scan 颠簸）。这是下一课 RRIP 要打的点，本课只承认 LRU 不是万能。PLRU 在真 LRU 与随机之间：大多数 SPECint 差距小，实现频率更好。</p><p>与 <a href="/cs/vipt-cache">VIPT</a> 无关：替换发生在命中/缺失判定之后，用的是物理标签那一组。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 RRIP 的 SRRIP/BRRIP，下一课。也不把操作系统的页面 LRU 与 cache 行 LRU 写成同一个结构——页替换是 OS 课，虽然栈直觉相同。预取填入该标成 MRU 还是 LRU，影响污染，是预取课。</p><p>后课默认：组相联默认 PLRU 或真 LRU；扫描式工作集会打穿 LRU。再引用间隔预测是下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>真 LRU 逼近 Belady，路多则用 PLRU 降位数。</li><li>扫描访问让 LRU 颠簸，这是 RRIP 的动机。</li><li>出处：Hennessy and Patterson, <em>CA:AQA</em>；Belady MIN。</li></ul>',9))])}const _=s(d,[["render",U]]);export{B as __pageData,_ as default};
